function minOperations(nums) {
  // Clear the values from smallest to largest. When value v is cleared, every smaller value is already 0, so each
  // block of non-zero elements that contains v costs exactly one operation (its minimum is v).
  const arr = nums.slice();
  const values = [...new Set(arr)].filter(v => v > 0).sort((a, b) => a - b);
  let total = 0;
  for (const v of values) {
    let i = 0;
    while (i < arr.length) {
      if (arr[i] === 0) { i++; continue; }
      let j = i, hasV = false;
      while (j < arr.length && arr[j] !== 0) { if (arr[j] === v) hasV = true; j++; }
      if (hasV) total++;
      i = j;
    }
    for (let k = 0; k < arr.length; k++) if (arr[k] === v) arr[k] = 0;
  }
  return total;
}

