function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size !== 'large') {
    const n = int(1, 9), top = int(1, 5), zeros = rand() * 0.3;
    return [Array.from({ length: n }, () => (rand() < zeros ? 0 : int(0, top)))];
  }
  const n = int(1500, 2000), mode = int(0, 3);
  if (mode === 0) return [Array.from({ length: n }, () => int(0, 100000))];
  if (mode === 1) return [Array.from({ length: n }, () => int(0, 6))];
  if (mode === 2) {
    // Rising and falling runs: long increasing chains on the stack, then sudden drops.
    let value = int(1, 50);
    return [Array.from({ length: n }, () => { value = Math.max(0, Math.min(100000, value + (rand() < 0.75 ? int(0, 40) : -int(0, 120)))); return value; })];
  }
  // A few levels repeated in valleys: equal values often reconnect over larger ones.
  const levels = Array.from({ length: int(2, 8) }, () => int(1, 100000)).sort((a, b) => a - b);
  return [Array.from({ length: n }, (_, i) => levels[Math.floor(Math.abs(Math.sin(i / int(5, 30))) * levels.length) % levels.length])];
}
